Record mchrH (mem : word -> option byte) (s : word) (buf : list byte) (K n : Z) : Prop := MCHRH {
  (* [comment removed for export] *)
  Hbuf : rdn RSEGS mem s (length buf) = Some buf;
  (* [comment removed for export] *)
  Hwin : ((bv_unsigned s + K) / 8 * 8 + 8 <= bv_unsigned s + Z.of_nat (length buf))%Z;
  Hnw  : (bv_unsigned s + Z.of_nat (length buf) < 2 ^ 64)%Z;
  (* [comment removed for export] *)
  HK0  : (0 <= K)%Z;
  Hzero : bv_unsigned (nth (Z.to_nat K) buf (Z_to_bv 8 0)) = 0%Z;
  Hnz  : forall j, (j < Z.to_nat K)%nat -> bv_unsigned (nth j buf (Z_to_bv 8 0)) <> 0%Z;
  (* [comment removed for export] *)
  HKn  : (K + 8 <= n)%Z;
  Hn64 : (n < 2 ^ 64)%Z;
  Hro  : rodata_clear mem }.
End FPX1.

Section MCHR.
  Context {fx : OssFuzzTheorems.Proofs.boost_json.fuzz_parse.lib.PropExec.FPState}.
  Variable mem : ltac2:(zQ "30!hc!jf!ine>0@1$1@1$0#k0@1$2@1$1@1$0#8").
  Variable s : word.
  Variable buf : ltac2:(zQ "30!lc!hc!jf@1$0@1$2@1$1#8").
  Variables K n : Z.
  Variable rom : ltac2:(zQ "30!hc!jf!ine>0@1$1@1$0#k0@1$2@1$1@1$0#8").
  Hypothesis HOK : ltac2:(zQ "10!mp4@5$0?3mem?1s?3buf?1K?1n").

  #[local] Notation L := (Z.of_nat (length buf)).
  Definition b_ : ltac2:(zQ "30!hc!h9!jf>1j$1@1$2@1$0#8") := ltac2:(zQ "60!hc!imf!h9!jmb!q2!jf\1j$2@4$1@1$5@1$0#8@1$3^1?3buf@2$4@1$0#8Z").
  Definition sb_ : ltac2:(zQ "50!lc!se!hc!h9!jf>1j$3>1m$1@1$0@1$4@1$2#8") := ltac2:(zQ "60!se!hc!h9!jld!jmb!jf\1j$2\1m$0@4$3@1$5@1$1#8?3buf@1$4^2^1").

  Let Hbuf := Hbuf _ _ _ _ _ HOK.
